#!/usr/bin/env bash

# Scenario runner for dart-testing-cli.
#
# The chain model mirrors the Confidential Assets pallet: each party's proof updates
# ITS OWN tree, and counterparty proofs verify against the root the OTHER side
# published at the last block end — so `end-block` steps go between inter-party
# state transitions (sender-affirm -> end-block -> receiver-affirm -> ...), exactly
# like a block-building client driving a node.
#
# Proof subcommands support `-w FILE` (generate proof only), `-r FILE` (apply a
# proof generated by a *compatible* CLI version), and `--dry-run`.

set -e

# Run everything from this script's directory.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# This package lives in the polymesh-dart workspace: cargo builds land in the workspace target dir.
EXE="../target/release/dart-testing-cli"
if [[ ! -x "$EXE" ]]; then
  echo "Building the dart-testing-cli executable..."
  cargo build --release -p dart-testing-cli
fi

# Record every applied transaction into a corpus (`corpus.jsonl`) and keep a chain snapshot in
# a separate DB (`corpus.db`). The main `dart_test.db` can be reset without losing the session.
REC="--record corpus.jsonl"

# Deterministic seed stored by `init`; every later command defaults to it, so the whole
# run replays byte-for-byte (change it for your own runs).
SEED="0000000000000001"

rm -rf curve-trees dart_test.db trace.jsonl *_proof.dat *_key.dat pub_key_*.dat corpus.jsonl corpus.db corpus.replay.db replay-run

echo "==========================="
echo "Starting the test script..."
echo "==========================="

$EXE $REC init --seed "$SEED"

echo "Running signer and account creation (block 1)..."
$EXE $REC create-signer -n issuer
$EXE $REC create-signer -n issuer1
$EXE $REC create-signer -n investor
$EXE $REC create-signer -n mediator
$EXE $REC create-signer -n relayer
$EXE $REC create-account -s issuer-0
$EXE $REC create-account -s issuer1-0
$EXE $REC create-account -s investor-0
$EXE $REC create-account -s mediator-0
$EXE $REC create-account -s relayer-0
$EXE $REC account-registration -s issuer-0   -w issuer-0-account.proof
$EXE $REC account-registration -s issuer-0 -r issuer-0-account.proof
$EXE $REC account-registration -s issuer1-0  -w issuer1-0-account.proof
$EXE $REC account-registration -s issuer1-0 -r issuer1-0-account.proof
$EXE $REC account-registration -s investor-0 -w investor-0-account.proof
$EXE $REC account-registration -s investor-0 -r investor-0-account.proof
$EXE $REC account-registration -s mediator-0 -w mediator-0-account.proof
$EXE $REC account-registration -s mediator-0 -r mediator-0-account.proof
$EXE $REC account-registration -s relayer-0 -w relayer-0-account.proof
$EXE $REC account-registration -s relayer-0 -r relayer-0-account.proof
$EXE $REC list-accounts
$EXE $REC end-block

echo "Creating assets (block 2): asset 0 is the fee asset, asset 1 is 'test_accept'..."
$EXE $REC create-asset -s issuer-0 -t mediator -a mediator-0 --name fee-asset --decimals 0
$EXE $REC create-asset -s issuer-0 -t mediator -a mediator-0 --name test_accept --decimals 6
$EXE $REC register-account -s issuer-0 --asset 1
$EXE $REC register-account -s issuer1-0 --asset 1
$EXE $REC register-account -w investor-0-register.proof -s investor-0 --asset 1
$EXE $REC register-account -r investor-0-register.proof -s investor-0 --asset 1
$EXE $REC end-block

echo "Minting (block 3)..."
$EXE $REC mint-assets -s issuer-0 -a 1 -m 1000 -w mint1-proof.dat
$EXE $REC mint-assets -s issuer-0 -a 1 -m 1000 -r mint1-proof.dat
$EXE $REC end-block

echo "Fee accounts (block 4): register + topup feed the fee pool; replay burns the nullifier"
$EXE $REC register-fee-accounts -s issuer-0 -f issuer-0:100 -w regfee-proof.dat
$EXE $REC register-fee-accounts -s issuer-0 -f issuer-0:100 -r regfee-proof.dat
$EXE $REC end-block
$EXE $REC topup-fee-accounts -s issuer-0 -f issuer-0:200 -w topupfee-proof.dat
$EXE $REC topup-fee-accounts -s issuer-0 -f issuer-0:200 -r topupfee-proof.dat
$EXE $REC end-block
$EXE $REC list-fee-accounts

echo "Encryption keys (block 6): register fresh auditor keys; distribute a shared key to the mediator"
$EXE $REC register-encryption-keys -s investor-0 -n 2 -w enc-keys-proof.dat
$EXE $REC register-encryption-keys -s investor-0 -r enc-keys-proof.dat
$EXE $REC end-block
$EXE $REC distribute-encryption-key -s investor-0 -R mediator-0 -w distribute-proof.dat
$EXE $REC distribute-encryption-key -s investor-0 -r distribute-proof.dat
$EXE $REC end-block

echo "Settlement 1: sender-affirm, receiver-affirm, mediator reject (finalizes: no pending finals)"
$EXE $REC create-settlement -v test_accept -l issuer-0:investor-0:1:500
$EXE $REC sender-affirm -s issuer-0 -S 1 -l 0 -a 1 -m 500 -w sender-affirm1-proof.dat
$EXE $REC sender-affirm -s issuer-0 -S 1 -l 0 -r sender-affirm1-proof.dat
$EXE $REC end-block
$EXE $REC receiver-affirm -s investor-0 -S 1 -l 0 -a 1 -m 500 -w receiver-affirm1-proof.dat
$EXE $REC receiver-affirm -s investor-0 -S 1 -l 0 -r receiver-affirm1-proof.dat
$EXE $REC end-block
# Pallet semantics: a mediator rejection finalizes the settlement immediately when no
# *final* affirmation (instant affirmations) is pending.  Revert-affirmations only apply
# to a Pending/Rejected settlement (i.e. after an instant affirmation rejected it), and
# replaying an applied proof fails with AffirmationAlreadySubmitted — by design.
$EXE $REC mediator-affirm -s mediator-0 -S 1 -l 0 --reject -w mediator-affirm1-proof.dat
$EXE $REC mediator-affirm -s mediator-0 -S 1 -l 0 --reject -r mediator-affirm1-proof.dat
$EXE $REC end-block

echo "Settlement 2: full lifecycle through receiver-claim and sender-counter-update"
$EXE $REC create-settlement -v test_accept -l issuer-0:investor-0:1:500
$EXE $REC sender-affirm -s issuer-0 -S 2 -l 0 -a 1 -m 500 -w sender-affirm2-proof.dat
$EXE $REC sender-affirm -s issuer-0 -S 2 -l 0 -r sender-affirm2-proof.dat
$EXE $REC end-block
$EXE $REC receiver-affirm -s investor-0 -S 2 -l 0 -a 1 -m 500 -w receiver-affirm2-proof.dat
$EXE $REC receiver-affirm -s investor-0 -S 2 -l 0 -r receiver-affirm2-proof.dat
$EXE $REC end-block
$EXE $REC mediator-affirm -s mediator-0 -S 2 -l 0 --accept -w mediator-affirm2-proof.dat
$EXE $REC mediator-affirm -s mediator-0 -S 2 -l 0 --accept -r mediator-affirm2-proof.dat
$EXE $REC end-block
$EXE $REC receiver-claim -s investor-0 -S 2 -l 0 -w receiver-claim2-proof.dat
$EXE $REC end-block
$EXE $REC sender-counter-update -s issuer-0 -S 2 -l 0 -w counter-update2-proof.dat
$EXE $REC sender-counter-update -s issuer-0 -S 2 -l 0 -r counter-update2-proof.dat
$EXE $REC end-block

echo "Settlement 3: create + sender-affirm in ONE atomic batch (submit_batched_proofs)"
$EXE $REC mint-assets -s issuer-0 -a 1 -m 500 -w mint3-proof.dat
$EXE $REC mint-assets -s issuer-0 -a 1 -m 500 -r mint3-proof.dat
$EXE $REC end-block
$EXE $REC create-settlement -v test_accept -l issuer-0:investor-0:1:100 -w create3-proof.dat
$EXE $REC sender-affirm -s issuer-0 -S 3 -l 0 -a 1 -m 100 -w sender-affirm3-proof.dat
$EXE $REC submit-batched-proofs -w batch3-proof.dat -p create-settlement=create3-proof.dat -p sender-affirm=sender-affirm3-proof.dat
$EXE $REC submit-batched-proofs -r batch3-proof.dat
$EXE $REC end-block
$EXE $REC show-legs -S 3

echo "Relayer path: party proofs bound to a relayer fee ctx; the paid batch is atomic-but-paid"
$EXE $REC register-fee-accounts -s relayer-0 -f relayer-0:60 -w regfee-relayer-proof.dat
$EXE $REC register-fee-accounts -s relayer-0 -f relayer-0:60 -r regfee-relayer-proof.dat
$EXE $REC end-block
NUL=$($EXE $REC relayer-fee-preview -s relayer-0 -m 20)
echo "relayer fee nullifier preview: $NUL"
$EXE $REC mint-assets -s issuer-0 -a 1 -m 300 -w mint4-proof.dat
$EXE $REC mint-assets -s issuer-0 -a 1 -m 300 -r mint4-proof.dat
$EXE $REC end-block
settle_id=$($EXE $REC create-settlement -v test_accept -l issuer-0:investor-0:1:200 -w create4-proof.dat --relayer-fee-nullifier "$NUL" | sed "s/^Created settlement \([0-9]*\).*/\1/")
echo "settlement $settle_id created (proof written)"
$EXE $REC sender-affirm -s issuer-0 -S "$settle_id" -l 0 -w sender-affirm4-proof.dat --relayer-fee-nullifier "$NUL"
$EXE $REC receiver-affirm -s investor-0 -S "$settle_id" -l 0 -w receiver-affirm4-proof.dat --relayer-fee-nullifier "$NUL"
$EXE $REC mediator-affirm -s mediator-0 -S "$settle_id" -l 0 --accept -w mediator-affirm4-proof.dat --relayer-fee-nullifier "$NUL"
$EXE $REC relayer-batched-proofs -s relayer-0 -m 20 -p create-settlement=create4-proof.dat -p sender-affirm=sender-affirm4-proof.dat -p receiver-affirm=receiver-affirm4-proof.dat -p mediator-affirm=mediator-affirm4-proof.dat
# Commit the party leaves from the relayer batch so the session DB ends on a clean block and
# new proofs can be generated against it.
$EXE $REC end-block
$EXE $REC get-settlement -S "$settle_id"
$EXE $REC list-fee-accounts

echo "Running get-settlement..."
$EXE $REC get-settlement -S 1
$EXE $REC get-settlement -S 2

echo "Running show-legs..."
$EXE $REC show-legs -S 1
$EXE $REC show-legs -S 2

echo "Running list-transactions (dispatch trace)..."
$EXE $REC trace

echo "Running list-assets..."
$EXE $REC list-assets

echo "Replaying the recorded corpus into a scratch DB (the main DB is untouched)..."
$EXE $REC --run-dir replay-run replay corpus.jsonl

echo "==========================="
echo "Finished test script!"
echo "==========================="
